Sort lock acquisitions by memory address to enforce a consistent lock hierarchy.
```c
void balance(Queue *q1, Queue *q2) {
    Queue *first = q1 < q2 ? q1 : q2;
    Queue *second = q1 < q2 ? q2 : q1;
    spin_lock(&first->lock);
    spin_lock(&second->lock);
    rebalance(q1, q2);
    spin_unlock(&second->lock);
    spin_unlock(&first->lock);
}
